// Assembles registry.json from the fragments in registry/*.json (ui.json is
// generated by scripts/generate.mjs), then (unless --check) runs
// `shadcn build` into public/r.
//
//   node scripts/build-registry.mjs          write registry.json + public/r
//   node scripts/build-registry.mjs --check  validate only; exit 1 on problems
//
// Built items import each other and the motion files they use through the
// app's `@/` aliases, the way shadcn's own items do, so the CLI maps them onto
// the app's aliases; an item's own files import each other relatively, and an
// alias shadcn would resolve to a same-named file is pinned to its file
// (scripts/shadcn-imports.mjs). Client modules get "use client". Registry dependencies
// become URLs under YOUJ_REGISTRY_URL: the docs site serves motion's and
// UI's items side by side, so youj-core or icon-check sit next to button.
//
// Both modes fail on an item that uses a motion preset class without
// youj-presets, or imports something its dependencies don't bring
// (scripts/import-closure.mjs).
import { execFileSync } from 'node:child_process'
import { existsSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { readsUndeclaredProcess, SOURCES, sourceItems } from '../../../scripts/youj-sources.mjs'
import { presetClassPattern, usesPresetClass } from '../../core/scripts/presets.mjs'
import { installedSource } from './app-imports.mjs'
import { importClosureProblems } from './import-closure.mjs'
import { motionEntries } from './motion-exports.mjs'
import { importPins, misroutedImports, pinImports, servedItems } from './shadcn-imports.mjs'

const root = join(import.meta.dirname, '..')
const check = process.argv.includes('--check')
const problems = []

function readFragments(dir, label) {
  const items = []
  for (const file of readdirSync(dir).filter((f) => f.endsWith('.json')).sort()) {
    let parsed
    try {
      parsed = JSON.parse(readFileSync(join(dir, file), 'utf8'))
    } catch (e) {
      problems.push(`${label}/${file}: invalid JSON (${e.message})`)
      continue
    }
    if (!Array.isArray(parsed)) problems.push(`${label}/${file}: must be an array of items`)
    else items.push(...parsed)
  }
  return items
}

const items = readFragments(join(root, 'registry'), 'registry')
// Motion's, the icons' and the illustrations' items: UI's items depend on them by name.
const motionItems = sourceItems()
const motionNames = new Set(motionItems.map((i) => i.name))

const names = new Set()
const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))
const presetPattern = presetClassPattern()
// devDependencies count: blocks may use libraries the package itself doesn't
// (the auth blocks validate with zod), and the registry installs them per item.
const declared = new Set(Object.keys({ ...pkg.dependencies, ...pkg.peerDependencies, ...pkg.devDependencies }))
for (const item of items) {
  if (names.has(item.name)) problems.push(`duplicate item name: ${item.name}`)
  if (motionNames.has(item.name)) problems.push(`${item.name}: ${motionItems.find((i) => i.name === item.name).package} has an item of the same name; the docs registry serves both`)
  names.add(item.name)
  for (const f of item.files ?? []) {
    if (!existsSync(join(root, f.path))) problems.push(`${item.name}: missing file ${f.path}`)
    // Without youj-presets, an install gets the class but not the CSS behind it.
    else if (usesPresetClass(readFileSync(join(root, f.path), 'utf8'), presetPattern) && !item.registryDependencies?.includes('youj-presets')) {
      problems.push(`${item.name}: ${f.path} uses a motion preset class, so the item needs registryDependencies "youj-presets"`)
    }
  }
  for (const dep of item.dependencies ?? []) {
    const base = dep.startsWith('@') ? dep.split('@').slice(0, 2).join('@') : dep.split('@')[0]
    if (!declared.has(base)) problems.push(`${item.name}: dependency "${dep}" is not in package.json dependencies`)
  }
}
const known = (dep) => names.has(dep) || motionNames.has(dep)
for (const item of items) {
  for (const dep of item.registryDependencies ?? []) {
    if (!dep.includes('/') && !known(dep)) problems.push(`${item.name}: unknown registryDependency "${dep}"`)
  }
}
// Every served item's code, ours and the source packages': a copy that reads process.env without declaring it fails the app's typecheck.
const sourceDir = (pkg) => join(root, '..', SOURCES.find((s) => s.name === pkg).dir)
for (const item of [...items.map((i) => ({ ...i, dir: root })), ...motionItems.map((i) => ({ ...i, dir: sourceDir(i.package) }))])
  for (const f of item.files ?? []) {
    const path = join(item.dir, f.path)
    if (/\.tsx?$/.test(f.path) && existsSync(path) && readsUndeclaredProcess(readFileSync(path, 'utf8'), f.path))
      problems.push(`${item.name}: ${f.path} reads process.env without declare const process: { env: { NODE_ENV?: string } } (apps without Node's types, like Vite's, fail to typecheck the copy)`)
  }
const entries = motionEntries()
if (!problems.length) problems.push(...importClosureProblems({ root, items, motionItems, entries }))
const served = servedItems(root, entries)
const pins = importPins(served)
const pinned = served.map((item) => ({ ...item, files: item.files.map((f) => ({ ...f, content: pinImports(f.content, f.target, pins) })) }))
for (const m of misroutedImports(pinned)) problems.push(`${m.item}: ${m.file} imports ${m.specifier} (${m.want}), which shadcn would point at ${m.got}`)

if (problems.length) {
  console.error(problems.map((p) => `  ✗ ${p}`).join('\n'))
  console.error(`\n${problems.length} registry problem(s)`)
  process.exit(1)
}

// Fragments name items; shadcn needs URLs (a bare name means shadcn's own registry).
const base = process.env.YOUJ_REGISTRY_URL ?? 'http://localhost:6006/r'
for (const item of items) {
  if (item.registryDependencies) {
    item.registryDependencies = item.registryDependencies.map((d) => (known(d) ? `${base}/${d}.json` : d))
  }
}

const registry = {
  $schema: 'https://ui.shadcn.com/schema/registry.json',
  name: 'youj',
  homepage: base.replace(/\/r$/, ''),
  items,
}
console.log(`registry: ${items.length} items`)
if (check) process.exit(0)

writeFileSync(join(root, 'registry.json'), JSON.stringify(registry, null, 2) + '\n')
// public/r is all build output: clear it so an item that moved to another package doesn't linger here.
rmSync(join(root, 'public/r'), { recursive: true, force: true })
execFileSync('pnpm', ['exec', 'shadcn', 'build', 'registry.json', '--output', 'public/r'], { cwd: root, stdio: 'inherit' })

for (const item of items) {
  const out = join(root, 'public/r', `${item.name}.json`)
  const built = JSON.parse(readFileSync(out, 'utf8'))
  const own = item.files.map((f) => f.path)
  for (const file of built.files ?? []) {
    if (/\.tsx?$/.test(file.path)) file.content = pinImports(installedSource(file.content, file.path, entries, own), file.path, pins)
  }
  writeFileSync(out, JSON.stringify(built, null, 2) + '\n')
}
